def mean(x): return sum(x) / len(x)
def median(x):
    s = sorted(x)
    n = len(s)
    m = n // 2
    return s[m] if n % 2 else (s[m-1] + s[m]) / 2
def var(x):
    m = mean(x)
    return sum((v - m) ** 2 for v in x) / (len(x) - 1)
