from math import log
tr = [('billing', 'invoice charged twice refund'), ('billing', 'refund payment failed invoice'), ('tech', 'app crashes on login error'), ('tech', 'error crash when uploading file'), ('account', 'reset password locked account'), ('account', 'change email account password')]
te = ['payment refund please', 'login error crash', 'locked out password reset']
vocab = {w for _, t in tr for w in t.split()}
cls = sorted({c for c, _ in tr})
cnt = {c: {} for c in cls}
for c, t in tr:
    for w in t.split():
        cnt[c][w] = cnt[c].get(w, 0) + 1
def sc(c, t):
    tot = sum(cnt[c].values())
    return sum(log((cnt[c].get(w, 0) + 1) / (tot + len(vocab))) for w in t.split() if w in vocab)
print([max(cls, key=lambda c: sc(c, t)) for t in te])

